//! Row formatting: mercator projection, EWKB hex, COPY text escaping,
//! hstore literals. Byte-exact compatibility with osm2pgsql's output is
//! the contract.
//!
//! Implemented by agent ROWFMT. Do not change the public interface.
//!
//! --- Extracted C++ semantics (provenance) ----------------------------------
//!
//! Mercator (contrib/libosmium/include/osmium/geom/mercator_projection.hpp
//! + osm2pgsql src/reprojection.cpp lonlat2merc()):
//! * osm2pgsql clamps latitude to [-89.99, 89.99] BEFORE projecting.
//!   osmium's lonlat_to_mercator() itself performs no validation/clamping.
//! * x = 6378137.0 * (lon * (PI/180.0))           [detail::lon_to_x]
//! * y: if lat < -78.0 || lat > 78.0 (checked *after* the 89.99 clamp):
//!        y = 6378137.0 * ln(tan(PI/4 + (lat*(PI/180.0))/2))
//!      else the fast rational polynomial (default path,
//!      OSMIUM_USE_SLOW_MERCATOR_PROJECTION is not defined anywhere in the
//!      osm2pgsql build), evaluated as (6378137.0 * num(lat)) / den(lat)
//!      with both polys in left-deep Horner form copied verbatim below.
//!   PI = 3.14159265358979323846 -> identical f64 as std::f64::consts::PI.
//!
//! EWKB (osm2pgsql src/wkb.cpp, little-endian host):
//! * header: 0x01 | u32(type | 0x20000000) LE | u32 srid(3857) LE
//! * point: + x,y f64 LE            => 25 bytes
//! * linestring: + u32 count LE + n*(x,y f64 LE) => 13 + 16n bytes;
//!   the C++ writer places NO lower bound on the point count, so an empty
//!   linestring is serialized as the 13-byte header with count 0.
//! * hex: uppercase, 2 chars/byte, osm2pgsql src/hex.cpp HEX_ENCODE_TABLE.
//!
//! COPY text escaping (osm2pgsql src/db-copy-mgr.hpp escape_and_add(),
//! used by add_value(char const*) with quote/bs escapes "\\\"" / "\\\\"):
//!   '"'  -> 5C 22   \ "
//!   '\\' -> 5C 5C   \ \
//!   0x0A -> 5C 6E   \ n
//!   0x0D -> 5C 72   \ r
//!   0x09 -> 5C 74   \ t
//!   all other bytes pass through unchanged.
//!
//! hstore value escaping (db-copy-mgr.hpp add_escaped_string(),
//! escapes R"(\\")" / R"(\\\\)"):
//!   '"'  -> 5C 5C 22            \ \ "
//!   '\\' -> 5C 5C 5C 5C         \ \ \ \
//!   0x0A -> 5C 6E ; 0x0D -> 5C 72 ; 0x09 -> 5C 74   (same as COPY)
//!   all other bytes pass through unchanged.
//! hstore literal (new_hash/add_hash_elem/finish_hash):
//!   '"' esc(k) '"' '=' '>' '"' esc(v) '"' per pair, pairs joined by ',',
//!   no leading/trailing markers; finish_hash() only swaps the final ','
//!   for the COPY column delimiter '\t', which is not column content.
//!   Empty tag set -> empty column content. The hstore content is appended
//!   to the COPY buffer verbatim (no second COPY-level escaping pass).

// ---------------------------------------------------------------------------
// Mercator
// ---------------------------------------------------------------------------

/// osmium::geom::detail::earth_radius_for_epsg3857
const EARTH_RADIUS: f64 = 6378137.0;

/// osmium::geom::deg_to_rad(d) == d * (PI / 180.0); PI/180.0 constant-folds
/// to the same double as in the C++ constexpr (IEEE round-to-nearest).
const DEG_TO_RAD: f64 = std::f64::consts::PI / 180.0;

/// osmium::geom::PI / 4 (division by 4 is exact in binary FP).
const PI_OVER_4: f64 = std::f64::consts::PI / 4.0;

/// Project lon/lat (degrees) to EPSG:3857 meters.
/// Must be bit-identical to osmium::geom::lonlat_to_mercator (the fast
/// polynomial path), see
/// contrib/libosmium/include/osmium/geom/mercator_projection.hpp.
///
/// Returns (x, y) = (easting, northing) in meters, matching the order in
/// which osm2pgsql writes point coordinates into EWKB (x first).
///
/// Includes the +-89.99 degree latitude clamp from osm2pgsql's
/// src/reprojection.cpp lonlat2merc() (the actual hot path); osmium's
/// lonlat_to_mercator() has no other normalization/validation.
pub fn to_mercator(lat_deg: f64, lon_deg: f64) -> (f64, f64) {
    // osm2pgsql src/reprojection.cpp lonlat2merc():
    //   if (coords.y > 89.99) coords.y = 89.99;
    //   else if (coords.y < -89.99) coords.y = -89.99;
    let mut lat = lat_deg;
    if lat > 89.99 {
        lat = 89.99;
    } else if lat < -89.99 {
        lat = -89.99;
    }

    // osmium::geom::detail::lon_to_x(lon) = earth * deg_to_rad(lon)
    let x = EARTH_RADIUS * (lon_deg * DEG_TO_RAD);

    let y = if lat < -78.0 || lat > 78.0 {
        // osmium::geom::detail::lat_to_y_with_tan(lat):
        //   earth * log(tan(PI/4 + deg_to_rad(lat)/2))
        EARTH_RADIUS * f64::ln(f64::tan(PI_OVER_4 + ((lat * DEG_TO_RAD) / 2.0)))
    } else {
        // osmium::geom::detail::lat_to_y(lat), fast path: rational
        // polynomial, coefficients and left-deep Horner evaluation order
        // copied verbatim from mercator_projection.hpp so that the IEEE-754
        // double operation sequence (and hence the result bits) is identical.
        let num = (((((((((-3.1112583378460085319e-23_f64 * lat
            + 2.0465852743943268009e-19) * lat
            + 6.4905282018672673884e-18) * lat
            + -1.9685447939983315591e-14) * lat
            + -2.2022588158115104182e-13) * lat
            + 5.1617537365509453239e-10) * lat
            + 2.5380136069803016519e-9) * lat
            + -5.1448323697228488745e-6) * lat
            + -9.4888671473357768301e-6) * lat
            + 1.7453292518154191887e-2) * lat;
        let den = (((((((((-1.9741136066814230637e-22_f64 * lat
            + -1.258514031244679556e-20) * lat
            + 4.8141483273572351796e-17) * lat
            + 8.6876090870176172185e-16) * lat
            + -2.3298743439377541768e-12) * lat
            + -1.9300094785736130185e-11) * lat
            + 4.3251609106864178231e-8) * lat
            + 1.7301944508516974048e-7) * lat
            + -3.4554675198786337842e-4) * lat
            + -5.4367203601085991108e-4) * lat
            + 1.0;
        // C++: earth_radius_for_epsg3857 * num / den, with * and /
        // left-associative, i.e. (earth * num) / den.
        (EARTH_RADIUS * num) / den
    };

    (x, y)
}

// ---------------------------------------------------------------------------
// EWKB hex
// ---------------------------------------------------------------------------

/// osm2pgsql src/wkb.cpp: geometry_type::wkb_srid SRID-presence flag (EWKB).
const WKB_SRID_FLAG: u32 = 0x2000_0000;
/// osm2pgsql src/wkb.cpp: geometry_type::wkb_point
const WKB_POINT: u32 = 1;
/// osm2pgsql src/wkb.cpp: geometry_type::wkb_line
const WKB_LINE: u32 = 2;
/// SRID osm2pgsql uses for projected (spherical mercator) geometries.
const SRID_3857: u32 = 3857;

/// Uppercase hex digits, same table as osm2pgsql src/hex.cpp encode_hex().
const HEX_DIGITS: &[u8; 16] = b"0123456789ABCDEF";

/// Append the uppercase hex encoding of `bytes`. The caller must have
/// reserved `bytes.len() * 2` bytes of capacity on `buf`.
#[inline]
fn append_hex_bytes(buf: &mut String, bytes: &[u8]) {
    for &b in bytes {
        buf.push(HEX_DIGITS[(b >> 4) as usize] as char);
        buf.push(HEX_DIGITS[(b & 0x0f) as usize] as char);
    }
}

/// Append the uppercase-hex EWKB encoding of POINT(x y) with SRID 3857,
/// exactly as osm2pgsql's geom_to_ewkb() + util::encode_hex() produce it.
///
/// Binary layout (25 bytes, osm2pgsql src/wkb.cpp write_point/write_header,
/// little-endian host):
/// ```text
/// [0]      0x01                     little-endian byte-order marker
/// [1..5]   0x20000001 u32 LE        wkb_point | wkb_srid
/// [5..9]   3857       u32 LE        SRID
/// [9..17]  x          f64 LE
/// [17..25] y          f64 LE
/// ```
/// => exactly 50 hex chars are appended.
pub fn append_point_hex(buf: &mut String, x: f64, y: f64) {
    let mut wkb = [0u8; 25];
    wkb[0] = 1; // wkb_byte_order_type_t::Endian (little endian)
    wkb[1..5].copy_from_slice(&(WKB_POINT | WKB_SRID_FLAG).to_le_bytes());
    wkb[5..9].copy_from_slice(&SRID_3857.to_le_bytes());
    wkb[9..17].copy_from_slice(&x.to_le_bytes());
    wkb[17..25].copy_from_slice(&y.to_le_bytes());

    // The hex encoding doubles the size; reserve the exact final length so
    // encoding cannot reallocate (cf. db_copy_mgr_t::add_hex_geom).
    buf.reserve(wkb.len() * 2);
    append_hex_bytes(buf, &wkb);
}

/// Append the uppercase-hex EWKB encoding of LINESTRING with SRID 3857.
///
/// Binary layout (13 + 16*n bytes, src/wkb.cpp write_linestring/write_points,
/// little-endian host):
/// ```text
/// [0]       0x01                    little-endian byte-order marker
/// [1..5]    0x20000002 u32 LE       wkb_line | wkb_srid
/// [5..9]    3857        u32 LE      SRID
/// [9..13]   n           u32 LE      point count (0 allowed: the C++ writer
///                                   performs no minimum-count check)
/// [13..]    n * (x f64 LE, y f64 LE)
/// ```
/// => exactly 2*(13 + 16n) hex chars are appended.
///
/// The incremental 16-bytes-per-point encoding below is byte-identical to
/// the C++ little-endian bulk copy of the point array: a (f64, f64) slice
/// element has the same layout as geom::point_t (two doubles, x first).
pub fn append_linestring_hex(buf: &mut String, pts: &[(f64, f64)]) {
    let n = pts.len() as u32;

    let mut header = [0u8; 13];
    header[0] = 1; // wkb_byte_order_type_t::Endian (little endian)
    header[1..5].copy_from_slice(&(WKB_LINE | WKB_SRID_FLAG).to_le_bytes());
    header[5..9].copy_from_slice(&SRID_3857.to_le_bytes());
    header[9..13].copy_from_slice(&n.to_le_bytes());

    // Reserve the exact final hex length up front.
    buf.reserve(2 * (13 + 16 * pts.len()));
    append_hex_bytes(buf, &header);
    for &(x, y) in pts {
        let mut pair = [0u8; 16];
        pair[0..8].copy_from_slice(&x.to_le_bytes());
        pair[8..16].copy_from_slice(&y.to_le_bytes());
        append_hex_bytes(buf, &pair);
    }
}

// ---------------------------------------------------------------------------
// COPY text escaping / hstore
// ---------------------------------------------------------------------------

/// Per-byte expansion of the COPY text path (every escape sequence there is
/// exactly 2 bytes, so each escapable byte adds 1).
const COPY_EXTRA: [u8; 256] = {
    let mut t = [0u8; 256];
    t[b'"' as usize] = 1; // '"' -> '\"'
    t[b'\\' as usize] = 1; // '\' -> '\\'
    t[b'\n' as usize] = 1; // 0x0A -> '\n'
    t[b'\r' as usize] = 1; // 0x0D -> '\r'
    t[b'\t' as usize] = 1; // 0x09 -> '\t'
    t
};

/// Per-byte expansion of the hstore-escaped path:
/// '"' -> 3 bytes (adds 2), '\' -> 4 bytes (adds 3), \n/\r/\t add 1.
const HSTORE_EXTRA: [u8; 256] = {
    let mut t = [0u8; 256];
    t[b'"' as usize] = 2;
    t[b'\\' as usize] = 3;
    t[b'\n' as usize] = 1;
    t[b'\r' as usize] = 1;
    t[b'\t' as usize] = 1;
    t
};

/// Rust literal for the plain COPY quote escape `\"` (0x5C 0x22).
const COPY_QUOTE_ESC: &str = "\\\"";
/// Rust literal for the plain COPY backslash escape `\\` (0x5C 0x5C).
const COPY_BACKSLASH_ESC: &str = "\\\\";
/// Rust literal for the hstore quote escape `\\"` (0x5C 0x5C 0x22);
/// this is the C++ raw string R"(\\")" from add_escaped_string().
const HSTORE_QUOTE_ESC: &str = "\\\\\"";
/// Rust literal for the hstore backslash escape `\\\\` (4 x 0x5C);
/// C++ raw string R"(\\\\)".
const HSTORE_BACKSLASH_ESC: &str = "\\\\\\\\";

/// Exact output length of escape_and_add() for `s`.
#[inline]
fn escaped_len(bytes: &[u8], extra: &[u8; 256]) -> usize {
    bytes.len() + bytes.iter().map(|&b| extra[b as usize] as usize).sum::<usize>()
}

/// Port of db_copy_mgr_t::escape_and_add(): append `s` to `buf`, escaping
/// exactly the characters '"', '\\', '\n', '\r', '\t'. `quote_esc` and
/// `backslash_esc` select the context-dependent replacement strings (plain
/// COPY text vs. hstore string), as in the C++.
fn escape_and_add(buf: &mut String, s: &str, quote_esc: &str, backslash_esc: &str, extra: &[u8; 256]) {
    let bytes = s.as_bytes();

    // Tight/exact capacity planning (mirrors the C++ output size exactly).
    let need = escaped_len(bytes, extra);
    if need == s.len() {
        // Fast path: nothing to escape.
        buf.reserve(s.len());
        buf.push_str(s);
        return;
    }
    buf.reserve(need);

    // Span-based copy: append runs of plain bytes in one go, then the
    // escape sequence for the special byte.
    let mut start = 0usize;
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if extra[b as usize] != 0 {
            if i > start {
                // start/i are always at ASCII byte positions, hence valid
                // UTF-8 char boundaries in `s`.
                buf.push_str(&s[start..i]);
            }
            match b {
                b'"' => buf.push_str(quote_esc),
                b'\\' => buf.push_str(backslash_esc),
                b'\n' => buf.push_str("\\n"),
                b'\r' => buf.push_str("\\r"),
                b'\t' => buf.push_str("\\t"),
                _ => unreachable!("extra table only flags these five bytes"),
            }
            i += 1;
            start = i;
        } else {
            i += 1;
        }
    }
    if start < bytes.len() {
        buf.push_str(&s[start..]);
    }
}

/// Append `s` to `buf` with the exact byte-level escaping osm2pgsql uses
/// for COPY text columns (db_copy_mgr_t::add_value(char const*)).
pub fn append_escaped(buf: &mut String, s: &str) {
    escape_and_add(buf, s, COPY_QUOTE_ESC, COPY_BACKSLASH_ESC, &COPY_EXTRA);
}

/// Append `s` with osm2pgsql's hstore-value escaping
/// (db_copy_mgr_t::add_escaped_string).
pub fn append_hstore_escaped(buf: &mut String, s: &str) {
    escape_and_add(buf, s, HSTORE_QUOTE_ESC, HSTORE_BACKSLASH_ESC, &HSTORE_EXTRA);
}

/// Append a complete hstore literal for `tags` exactly as osm2pgsql writes
/// it into the COPY stream (i.e. the content the COPY text column carries).
///
/// Reproduces new_hash() (writes nothing), add_hash_elem():
/// `"` esc(k) `"=>"` esc(v) `"` joined by `,`, and finish_hash() (which
/// only turns the final `,` into the COPY column delimiter `\t`, not part
/// of the column content). An empty tag set produces empty content, and
/// the hstore content is not additionally COPY-escaped.
pub fn append_hstore(buf: &mut String, tags: &[(String, String)]) {
    if tags.is_empty() {
        return;
    }

    // Exact final size: per pair 6 fixed bytes ('"', '"'=>' between the
    // parts, and closing '"': 1 + 4 + 1) plus escaped key and value; pairs
    // are joined by a single ',' (tags.len() - 1 separators).
    let mut size = tags.len() * 6 + (tags.len() - 1);
    for (k, v) in tags {
        size += escaped_len(k.as_bytes(), &HSTORE_EXTRA);
        size += escaped_len(v.as_bytes(), &HSTORE_EXTRA);
    }
    buf.reserve(size);

    let mut first = true;
    for (k, v) in tags {
        if !first {
            buf.push(',');
        }
        first = false;
        buf.push('"');
        escape_and_add(buf, k, HSTORE_QUOTE_ESC, HSTORE_BACKSLASH_ESC, &HSTORE_EXTRA);
        buf.push_str("\"=>\"");
        escape_and_add(buf, v, HSTORE_QUOTE_ESC, HSTORE_BACKSLASH_ESC, &HSTORE_EXTRA);
        buf.push('"');
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    // --- Mercator bit-exactness -------------------------------------------
    //
    // Expected (x_bits, y_bits) pairs generated by a C++ oracle program
    // (g++ -O2, output identical at -O0/-O2/-O3) that calls the real
    // osmium::geom::lonlat_to_mercator after the same +-89.99 clamp osm2pgsql
    // applies in src/reprojection.cpp. Each test input is regenerated here
    // with the identical IEEE-754 double operations (integer * same f64
    // literal), so input bits match the oracle's by construction; outputs
    // are compared as raw u64 bits.
    //
    // Oracle input grid, in order:
    //   for j in -50..=50: lat = j * 1.78
    //     for i in -50..=50: lon = i * 3.6          -> 10201 pairs
    //   then LAT_EDGES x LON_EDGES                  -> 100 pairs
    // total 10301 pairs, 32 hex chars each.
    const MERC_ORACLE_HEX: &str = "";

    const LAT_EDGES: [f64; 20] = [
        78.0, -78.0, 78.000000001, -78.000000001, 77.999999999, -77.999999999, 85.0511288,
        -85.0511288, 86.0, -86.0, 89.99, -89.99, 89.9900001, -89.9900001, 90.0, -90.0, 120.0,
        -120.0, 500.0, -500.0,
    ];
    const LON_EDGES: [f64; 5] = [-180.0, 0.0, -0.0, 180.0, 540.0];

    #[test]
    fn mercator_matches_osmium_bit_exactly() {
        let hex = MERC_ORACLE_HEX;
        assert_eq!(hex.len(), 10301 * 32, "oracle data size mismatch");
        let mut off = 0usize;
        let mut checked = 0u64;

        let mut check = |lat: f64, lon: f64| {
            let want_x = u64::from_str_radix(&hex[off..off + 16], 16).unwrap();
            let want_y = u64::from_str_radix(&hex[off + 16..off + 32], 16).unwrap();
            off += 32;
            let (x, y) = to_mercator(lat, lon);
            assert_eq!(
                want_x,
                x.to_bits(),
                "x bits mismatch at lat={lat:e} lon={lon:e}"
            );
            assert_eq!(
                want_y,
                y.to_bits(),
                "y bits mismatch at lat={lat:e} lon={lon:e}"
            );
            checked += 1;
        };

        for j in -50..=50i32 {
            let lat = j as f64 * 1.78;
            for i in -50..=50i32 {
                check(lat, i as f64 * 3.6);
            }
        }
        for &la in &LAT_EDGES {
            for &lo in &LON_EDGES {
                check(la, lo);
            }
        }

        assert_eq!(off, hex.len());
        assert_eq!(checked, 10301);
    }

    // --- EWKB hex ----------------------------------------------------------

    /// Independent hex encoder used as reference (uppercase, 2 chars/byte).
    fn ref_hex(bytes: &[u8]) -> String {
        use std::fmt::Write;
        let mut s = String::with_capacity(bytes.len() * 2);
        for b in bytes {
            write!(s, "{:02X}", b).unwrap();
        }
        s
    }

    /// Independent EWKB builder for POINT SRID 3857 per the documented
    /// byte layout.
    fn ref_point_ewkb(x: f64, y: f64) -> Vec<u8> {
        let mut v = Vec::with_capacity(25);
        v.push(1u8);
        v.extend_from_slice(&0x2000_0001u32.to_le_bytes());
        v.extend_from_slice(&3857u32.to_le_bytes());
        v.extend_from_slice(&x.to_le_bytes());
        v.extend_from_slice(&y.to_le_bytes());
        v
    }

    fn ref_line_ewkb(pts: &[(f64, f64)]) -> Vec<u8> {
        let mut v = Vec::with_capacity(13 + 16 * pts.len());
        v.push(1u8);
        v.extend_from_slice(&0x2000_0002u32.to_le_bytes());
        v.extend_from_slice(&3857u32.to_le_bytes());
        v.extend_from_slice(&(pts.len() as u32).to_le_bytes());
        for &(x, y) in pts {
            v.extend_from_slice(&x.to_le_bytes());
            v.extend_from_slice(&y.to_le_bytes());
        }
        v
    }

    fn assert_uppercase_hex(s: &str) {
        assert!(
            s.bytes().all(|b| b.is_ascii_digit() || (b'A'..=b'F').contains(&b)),
            "non-uppercase-hex char in {s:?}"
        );
    }

    #[test]
    fn point_hex_hand_verified() {
        // POINT(1.5 -2.25), hand-checked byte by byte:
        //   01                        little-endian marker
        //   01000020                  0x20000001 = WKB point | SRID flag, LE
        //   110F0000                  3857 = 0x00000F11, LE
        //   000000000000F83F          1.5  = 0x3FF8000000000000, LE
        //   00000000000002C0         -2.25 = 0xC002000000000000, LE
        let mut s = String::new();
        append_point_hex(&mut s, 1.5, -2.25);
        assert_eq!(
            s,
            concat!("0101000020", "110F0000", "000000000000F83F", "00000000000002C0")
        );
        assert_eq!(s.len(), 50);
        assert_uppercase_hex(&s);
    }

    #[test]
    fn linestring_hex_hand_verified_empty() {
        // Empty linestring: C++ write_linestring performs no point-count
        // check, so it writes the header plus a zero count (13 bytes).
        let mut s = String::new();
        append_linestring_hex(&mut s, &[]);
        assert_eq!(s, concat!("0102000020", "110F0000", "00000000"));
        assert_eq!(s.len(), 26);
    }

    #[test]
    fn hex_roundtrip_reference() {
        // A spread of doubles incl. NaN/Inf/denormal/-0.0 to prove raw byte
        // passthrough of the IEEE bit patterns.
        let vals = [
            0.0, -0.0, 1.5, -2.25, 20037508.34, -20037508.34, 1e-300, -1e-300, f64::MAX,
            -f64::MAX, f64::NAN, f64::INFINITY, f64::NEG_INFINITY, f64::MIN_POSITIVE,
        ];
        for &x in &vals {
            for &y in &vals {
                let mut s = String::new();
                append_point_hex(&mut s, x, y);
                assert_eq!(s, ref_hex(&ref_point_ewkb(x, y)));
                assert_eq!(s.len(), 50);
                assert_uppercase_hex(&s);
            }
        }

        let lines: Vec<Vec<(f64, f64)>> = vec![
            vec![],
            vec![(0.0, 0.0)],
            vec![(1.5, -2.25)],
            vec![(-0.0, 0.0), (f64::NAN, f64::INFINITY)],
            (0..17)
                .map(|i| (i as f64 * 3.7 - 30.1, i as f64 * -1.3e7))
                .collect(),
        ];
        for pts in &lines {
            let mut s = String::new();
            append_linestring_hex(&mut s, pts);
            assert_eq!(s, ref_hex(&ref_line_ewkb(pts)));
            assert_eq!(s.len(), 2 * (13 + 16 * pts.len()));
            assert_uppercase_hex(&s);
        }
    }

    #[test]
    fn hex_appends_to_nonempty_buffer() {
        let mut s = String::from("existing\t");
        append_point_hex(&mut s, 1.5, -2.25);
        assert!(s.starts_with("existing\t"));
        assert_eq!(&s[9..], ref_hex(&ref_point_ewkb(1.5, -2.25)));
    }

    // --- COPY / hstore escaping --------------------------------------------
    //
    // Straightforward byte-level reference implementations, ported 1:1 from
    // db-copy-mgr.hpp escape_and_add()/add_hash_elem()/finish_hash(), used
    // to fuzz-compare against the optimized versions.

    fn ref_escape_and_add(out: &mut Vec<u8>, s: &str, quote_esc: &[u8], bs_esc: &[u8]) {
        for &b in s.as_bytes() {
            match b {
                b'"' => out.extend_from_slice(quote_esc),
                b'\\' => out.extend_from_slice(bs_esc),
                b'\n' => out.extend_from_slice(b"\\n"),
                b'\r' => out.extend_from_slice(b"\\r"),
                b'\t' => out.extend_from_slice(b"\\t"),
                _ => out.push(b),
            }
        }
    }

    fn ref_escaped(s: &str) -> String {
        let mut v = Vec::new();
        ref_escape_and_add(&mut v, s, b"\\\"", b"\\\\");
        String::from_utf8(v).unwrap()
    }

    fn ref_hstore_escaped(s: &str) -> String {
        let mut v = Vec::new();
        // hstore escapes R"(\\")" = \ \ " and R"(\\\\)" = \ \ \ \
        ref_escape_and_add(&mut v, s, b"\\\\\"", b"\\\\\\\\");
        String::from_utf8(v).unwrap()
    }

    fn ref_hstore(tags: &[(&str, &str)]) -> String {
        let mut v = Vec::new();
        for (k, val) in tags {
            v.push(b'"');
            ref_escape_and_add(&mut v, k, b"\\\\\"", b"\\\\\\\\");
            v.extend_from_slice(b"\"=>\"");
            ref_escape_and_add(&mut v, val, b"\\\\\"", b"\\\\\\\\");
            v.extend_from_slice(b"\",");
        }
        // finish_hash(): the trailing ',' is replaced by the COPY column
        // delimiter '\t', which is not part of the column content.
        if v.last() == Some(&b',') {
            v.pop();
        }
        String::from_utf8(v).unwrap()
    }

    // Hand-checked hstore / escaping literals.
    #[test]
    fn escaping_hand_verified() {
        // Plain COPY escaping.
        let mut s = String::new();
        append_escaped(&mut s, "a\"b\\c\nd\re\tf");
        assert_eq!(s, "a\\\"b\\\\c\\nd\\re\\tf");
        assert_eq!(s.as_bytes(), b"a\\\"b\\\\c\\nd\\re\\tf");

        let mut s = String::new();
        append_escaped(&mut s, "");
        assert_eq!(s, "");

        // hstore single value escaping.
        let mut s = String::new();
        append_hstore_escaped(&mut s, "q\"w\\e\nr\tt\ru");
        assert_eq!(s.as_bytes(), b"q\\\\\"w\\\\\\\\e\\nr\\tt\\ru");

        // hstore literals.
        let mut s = String::new();
        append_hstore(&mut s, &[]);
        assert_eq!(s, "");

        let mut s = String::new();
        append_hstore(&mut s, &[("name".into(), "foo".into())]);
        assert_eq!(s.as_bytes(), b"\"name\"=>\"foo\"");

        let mut s = String::new();
        append_hstore(&mut s, &[("a".into(), "1".into()), ("b".into(), "2".into())]);
        assert_eq!(s.as_bytes(), b"\"a\"=>\"1\",\"b\"=>\"2\"");

        // key with quote: '"' -> \ \ " ; empty value
        let mut s = String::new();
        append_hstore(&mut s, &[("a\"b".into(), "".into())]);
        assert_eq!(s.as_bytes(), b"\"a\\\\\"b\"=>\"\"");

        // value with backslash: '\\' -> \ \ \ \ ; high-byte passthrough
        let mut s = String::new();
        append_hstore(&mut s, &[("k".into(), "a\\b Café \u{1F600}".into())]);
        assert_eq!(s.as_bytes(), b"\"k\"=>\"a\\\\\\\\b Caf\xc3\xa9 \xF0\x9F\x98\x80\"");
    }

    struct Rng(u64);
    impl Rng {
        fn next(&mut self) -> u64 {
            let mut x = self.0;
            x ^= x >> 12;
            x ^= x << 25;
            x ^= x >> 27;
            self.0 = x;
            x.wrapping_mul(0x2545_F491_4F6C_DD1D)
        }
    }

    fn rand_string(rng: &mut Rng, max_len: usize, escape_dense: bool) -> String {
        let len = (rng.next() as usize) % (max_len + 1);
        let mut s = String::with_capacity(len);
        for _ in 0..len {
            let class = rng.next() % 100;
            let c: char = if escape_dense && class < 55 {
                ['"', '\\', '\n', '\r', '\t'][(rng.next() % 5) as usize]
            } else if class < 75 {
                (0x20u8 + (rng.next() % 0x5F) as u8) as char // printable ASCII
            } else if class < 85 {
                char::from(0xA0u8 + (rng.next() % 0x60) as u8) // latin-1 high
            } else {
                char::from_u32((rng.next() % 0x3000) as u32).unwrap() // BMP, < surrogates
            };
            s.push(c);
        }
        s
    }

    #[test]
    fn escaping_fuzz_all_byte_values() {
        // Every byte value 0..=255, alone (as char; >=0x80 becomes 2-byte
        // UTF-8, exercising high-byte passthrough) and embedded in context.
        for b in 0u8..=255 {
            let c = char::from(b);
            for s in [c.to_string(), format!("x{c}y"), format!("{c}{c}")] {
                let mut a = String::new();
                append_escaped(&mut a, &s);
                assert_eq!(a, ref_escaped(&s), "plain escape mismatch on {s:?}");

                let mut h = String::new();
                append_hstore_escaped(&mut h, &s);
                assert_eq!(h, ref_hstore_escaped(&s), "hstore escape mismatch on {s:?}");
            }
        }
    }

    #[test]
    fn escaping_fuzz_random() {
        let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
        let mut cases = 0u64;
        for round in 0..100_000u32 {
            let escape_dense = round % 2 == 0;
            let s = rand_string(&mut rng, 40, escape_dense);

            // plain COPY escaping (fresh and prefixed buffers)
            let mut a = String::new();
            append_escaped(&mut a, &s);
            assert_eq!(a, ref_escaped(&s));
            let mut a2 = String::from("pre\tfix");
            append_escaped(&mut a2, &s);
            assert_eq!(a2, format!("pre\tfix{}", ref_escaped(&s)));

            // hstore value escaping
            let mut h = String::new();
            append_hstore_escaped(&mut h, &s);
            assert_eq!(h, ref_hstore_escaped(&s));
            cases += 1;

            // full hstore literal with 0..=4 pairs
            if round % 4 == 0 {
                let n_pairs = (rng.next() % 5) as usize;
                let pairs: Vec<(String, String)> = (0..n_pairs)
                    .map(|_| (rand_string(&mut rng, 12, true), rand_string(&mut rng, 20, escape_dense)))
                    .collect();
                let mut buf = String::new();
                append_hstore(&mut buf, &pairs);
                let refpairs: Vec<(&str, &str)> =
                    pairs.iter().map(|(k, v)| (k.as_str(), v.as_str())).collect();
                assert_eq!(buf, ref_hstore(&refpairs), "hstore mismatch on {pairs:?}");
                cases += 1;
            }
        }
        assert!(cases >= 100_000);
    }
}
